begin;

insert into public.hcd_reporting_indicators
(indicator_code, reporting_category, pillar, segment, indicator_name, definition, required_data_fields, measurement_unit, calculation_method, collection_method, recommended_source, reporting_frequency, disaggregation_dimensions, evidence_required, is_active)
values
-- EDUCATION
('EDU-01','Education','education',null,'School-age children enrolled in education','Number of school-age children enrolled in a recognized education programme during the reporting period.','["learners_enrolled","school_id","school_type","academic_year","enrolment_register_reference"]'::jsonb,'learners','Count unique enrolled learners for the reporting period; avoid double-counting transfers.','School register and enrolment return review','School/education authority enrolment registers','Termly',array['LGA','community','sex','age_group','school_type','disability_status'],array['enrolment register','school return'],true),
('EDU-02','Education','education',null,'Learner attendance rate','Percentage of scheduled learner-days attended during the reporting period.','["learner_days_present","learner_days_expected","period","attendance_register_reference"]'::jsonb,'percent','learner_days_present / learner_days_expected * 100; report N/A when expected learner-days are zero.','Attendance register review','School attendance registers and education monitoring returns','Termly',array['LGA','school','sex','grade','school_type'],array['attendance register','monitoring return'],true),
('EDU-03','Education','education',null,'Learners completing the academic cycle','Number and proportion of enrolled learners who complete the defined academic cycle.','["learners_at_start","learners_completed","academic_cycle","completion_register_reference"]'::jsonb,'learners and percent','Report completed learners and completion rate = learners_completed / learners_at_start * 100; explain transfers and exclusions.','School progression and completion record review','School registers and education management information system','Annually',array['LGA','sex','grade','school_type','disability_status'],array['completion register','annual school return'],true),
('EDU-04','Education','education',null,'Learners meeting defined literacy and numeracy proficiency','Number and share of assessed learners meeting the approved literacy and numeracy proficiency standard.','["learners_assessed","learners_meeting_standard","assessment_tool","grade","assessment_period"]'::jsonb,'learners and percent','Report learners meeting standard / learners assessed * 100 separately for literacy and numeracy; include the assessment standard.','Assessment result aggregation and verification','Approved learning assessment records','Termly',array['LGA','sex','grade','subject','school_type'],array['assessment tool','aggregated assessment results'],true),
('EDU-05','Education','education',null,'Teachers available against approved staffing requirement','Percentage of approved teacher posts filled by teachers available for service.','["approved_teacher_posts","teachers_available","school_id","staff_return_period"]'::jsonb,'percent','teachers_available / approved_teacher_posts * 100; report counts and vacancy totals.','Staff return and school verification','School staffing returns and education personnel records','Termly',array['LGA','community','school_type','level'],array['staffing return','verification record'],true),
('EDU-06','Education','education',null,'Schools meeting minimum learning-environment standards','Number and share of assessed schools meeting the applicable minimum infrastructure, WASH, accessibility and learning-resource standards.','["schools_assessed","schools_meeting_standard","standard_version","assessment_date","assessment_reference"]'::jsonb,'schools and percent','schools_meeting_standard / schools_assessed * 100; document each standard and any critical gaps.','School facility checklist and site verification','School infrastructure assessments and inspection records','Annually',array['LGA','community','school_type','education_level'],array['facility checklist','dated verification evidence'],true),

-- HEALTH
('HLT-01','Health','health',null,'Antenatal care coverage (four or more visits)','Percentage of women with a live birth during the reporting period who attended at least four antenatal care visits, where this indicator is used in the approved reporting framework.','["women_with_live_births","women_with_four_or_more_anc_visits","reporting_period","facility_or_register_reference"]'::jsonb,'percent','women_with_four_or_more_anc_visits / women_with_live_births * 100; state the denominator definition and source.','Maternal health register aggregation','Health facility ANC and delivery registers / approved HMIS return','Monthly',array['LGA','facility','age_group','facility_type'],array['aggregated ANC register','HMIS return'],true),
('HLT-02','Health','health',null,'Births attended by skilled health personnel','Percentage of recorded births attended by qualified skilled health personnel during the reporting period.','["total_recorded_births","births_attended_by_skilled_personnel","reporting_period","facility_or_register_reference"]'::jsonb,'percent','births_attended_by_skilled_personnel / total_recorded_births * 100; disclose facility and community data coverage.','Delivery register review and HMIS aggregation','Health facility delivery registers and approved HMIS returns','Monthly',array['LGA','facility','maternal_age_group','facility_type'],array['delivery register','HMIS return'],true),
('HLT-03','Health','health',null,'Penta 3 immunization coverage','Coverage of eligible infants receiving the third dose of pentavalent vaccine during the reporting period.','["eligible_infants_or_target_population","infants_receiving_penta3","reporting_period","immunization_register_reference"]'::jsonb,'percent','infants_receiving_penta3 / eligible_infants_or_target_population * 100; document the approved target-population source.','Immunization register and monthly return review','PHC immunization registers and approved immunization/HMIS reports','Monthly',array['LGA','facility','sex','settlement_type'],array['immunization register','monthly return'],true),
('HLT-04','Health','health',null,'Postnatal care coverage within the approved time window','Percentage of eligible mothers/newborns receiving documented postnatal care within the nationally or state-approved time window.','["eligible_mothers_or_newborns","mothers_or_newborns_receiving_pnc","approved_time_window","reporting_period"]'::jsonb,'percent','report recipients / eligible population * 100; report mothers and newborns separately when the source allows.','Postnatal register and HMIS return review','Facility postnatal registers and community health worker records','Monthly',array['LGA','facility','mother_or_newborn','age_group','facility_type'],array['postnatal register','HMIS return'],true),
('HLT-05','Health','health',null,'Primary healthcare service utilization','Number of outpatient consultations or visits recorded at supported primary healthcare facilities during the reporting period.','["outpatient_visits","facility_id","reporting_period","service_register_reference"]'::jsonb,'visits','Count recorded visits; distinguish visits from unique patients and disclose reporting-facility coverage.','Facility register aggregation and completeness checks','PHC outpatient registers and approved HMIS returns','Monthly',array['LGA','facility','sex','age_group','service_type'],array['outpatient register','monthly HMIS return'],true),
('HLT-06','Health','health',null,'Essential medicine availability at primary healthcare facilities','Percentage of assessed tracer essential medicines available on the day of facility assessment.','["tracer_medicines_assessed","tracer_medicines_available","assessment_date","facility_id","tracer_list_version"]'::jsonb,'percent','tracer_medicines_available / tracer_medicines_assessed * 100; record the tracer list and stock-out status.','Physical stock check and stock-card review','Facility pharmacy stock cards and supervision checklist','Monthly',array['LGA','facility','medicine_class','facility_type'],array['stock checklist','stock cards'],true),

-- SKILL AND LABOUR
('LAB-01','Skill and labour','vocational',null,'Participants enrolled in approved skills-development programmes','Number of participants enrolled in approved vocational, technical, digital or employability training during the reporting period.','["participants_enrolled","programme_id","trade_or_skill_area","training_provider","enrolment_period","register_reference"]'::jsonb,'people','Count unique enrolments and document the rule used for participants enrolled in multiple programmes.','Training-provider enrolment register review','Approved training provider and implementing MDA records','Quarterly',array['LGA','sex','age_group','skill_area','provider','disability_status'],array['enrolment register','programme approval/reference'],true),
('LAB-02','Skill and labour','vocational',null,'Participants completing skills training','Number and share of enrolled participants who complete the defined training programme.','["participants_enrolled","participants_completed","programme_id","completion_period","completion_register_reference"]'::jsonb,'people and percent','Report completed participants and completion rate = participants_completed / participants_enrolled * 100; if no enrolments, report N/A.','Training completion record verification','Training provider completion registers','Quarterly',array['LGA','sex','age_group','skill_area','provider'],array['completion register','training report'],true),
('LAB-03','Skill and labour','vocational',null,'Participants achieving competency certification','Number and share of programme completers who pass an approved competency assessment or receive a recognized certification.','["participants_completed","participants_certified","certification_body","assessment_standard","certification_period"]'::jsonb,'people and percent','Report certified participants and rate = participants_certified / participants_completed * 100; identify the certification standard.','Certificate register and awarding-body verification','Accredited training provider and certification body records','Quarterly',array['LGA','sex','age_group','skill_area','certification_body'],array['certificate register','assessment result or verification'],true),
('LAB-04','Skill and labour','vocational',null,'Graduates in employment or self-employment after training','Number and share of verified programme graduates in paid employment, self-employment or an operating enterprise at the defined follow-up point.','["graduates_traced","graduates_employed","graduates_self_employed","follow_up_months","verification_method"]'::jsonb,'people and percent','Report employment and self-employment separately; denominator is graduates successfully traced or the programme-defined cohort, clearly stated.','Graduate tracer survey and employer/enterprise verification','Implementing MDA, employer follow-up, graduate tracer survey','Quarterly',array['LGA','sex','age_group','skill_area','employment_type'],array['tracer survey summary','verification record'],true),
('LAB-05','Skill and labour','vocational',null,'Youth placed in apprenticeships, internships or work experience','Number of eligible youth commencing a verified apprenticeship, internship or structured work-experience placement during the reporting period.','["eligible_youth_placed","placement_type","employer_or_host","placement_start_date","placement_register_reference"]'::jsonb,'people','Count unique youth who commenced a verified placement; distinguish offers from placements actually started.','Placement register and host confirmation','Training provider, employer/host and implementing MDA records','Quarterly',array['LGA','sex','age_group','skill_area','placement_type'],array['placement register','host confirmation'],true),
('LAB-06','Skill and labour','vocational',null,'Supported enterprises operating after programme support','Number and share of supported participant-owned enterprises verified as operating at the defined follow-up point.','["enterprises_supported","enterprises_operating","follow_up_period","verification_method","enterprise_register_reference"]'::jsonb,'enterprises and percent','Report supported and operating enterprises; operating rate = enterprises_operating / enterprises_supported * 100, with the follow-up period stated.','Enterprise follow-up and site/transaction verification','Enterprise support programme records and follow-up checks','Quarterly',array['LGA','sex','age_group','enterprise_sector','support_type'],array['enterprise register','follow-up verification'],true)

